package handlers.skill.conditions;

import org.l2jmobius.gameserver.entity.WorldObject;
import org.l2jmobius.gameserver.entity.actor.Creature;
import org.l2jmobius.gameserver.mechanics.skill.ISkillCondition;
import org.l2jmobius.gameserver.mechanics.skill.Skill;
import org.l2jmobius.gameserver.util.StatSet;

/**
 * Checks if the target creature is not currently under a curse effect.<br>
 * This condition returns {@code true} if no active curses are detected on the entity.
 * @author Sdw
 */
public class OpNotCursedSkillCondition implements ISkillCondition
{
	/**
	 * Creates a new condition to check if an actor is not cursed.<br>
	 * This constructor initializes the condition using specific statistics.
	 * @param params The {@code StatSet} containing the required parameters.
	 */
	public OpNotCursedSkillCondition(StatSet params)
	{
	}
	
	/**
	 * Checks if the {@code caster} is allowed to use a specific {@code skill}.<br>
	 * This condition verifies that the {@code caster} is a player.<br>
	 * It also ensures the player does not have a cursed weapon equipped.
	 * @param caster The entity attempting to cast the skill.
	 * @param skill The {@code Skill} being used.
	 * @param target The {@code WorldObject} targeted by the skill.
	 * @return {@code true} if all conditions are met, otherwise {@code false}.
	 */
	@Override
	public boolean canUse(Creature caster, Skill skill, WorldObject target)
	{
		return caster.isPlayer() && !caster.asPlayer().isCursedWeaponEquipped();
	}
}
